import React, { useEffect } from 'react';

const MinimalPortfolio = () => {
  useEffect(() => {
    // Set page title
    document.title = 'RD/> Portfolio - Main';
  }, []);

  return (
    <div style={styles.container}>
      {/* Logo at top
      <img 
        src={logo} 
        alt="Logo" 
        style={styles.logo}
      /> */}

      {/* Name / Title */}
      <h1 style={styles.name}>Ranvir Deshmukh</h1>

      {/* Short Tagline */}
      <h2 style={styles.tagline}>
        Founder, Software Engineer, ML Researcher, Video Producer
      </h2>

      {/* Brief Bio / Description */}
      <p style={styles.description}>
        I’m currently building [Your Current Project]. <br />
        Previously built [any prior ventures]. <br />
        Studying Computer Science & Economics at Dartmouth. <br />
        Reach out — I’m always open to chat!
      </p>

      {/* Links */}
      <div style={styles.linkContainer}>
        <a 
          href="https://linkedin.com/in/YOUR_LINKEDIN"
          style={styles.linkStyle}
          target="_blank"
          rel="noopener noreferrer"
        >
          LinkedIn
        </a>
        <span style={styles.linkSeparator}>|</span>
        <a 
          href="https://github.com/YOUR_GITHUB"
          style={styles.linkStyle}
          target="_blank"
          rel="noopener noreferrer"
        >
          GitHub
        </a>
      </div>
    </div>
  );
};

const styles = {
  container: {
    backgroundColor: '#FFFFFF',
    color: '#000000',
    minHeight: '100vh',
    fontFamily: "'SF Pro Display', sans-serif",
    fontWeight: 500, // 'Medium' weight for SF Pro Display
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    padding: '0 20px',
  },
  logo: {
    width: '80px',
    height: 'auto',
    marginBottom: '30px',
  },
  name: {
    fontSize: '48px',
    margin: '0 0 10px 0',
    fontWeight: 600, // Slightly heavier for name
  },
  tagline: {
    fontSize: '18px',
    margin: '0 0 25px 0',
    opacity: 0.8,
  },
  description: {
    fontSize: '16px',
    maxWidth: '600px',
    textAlign: 'center',
    lineHeight: '1.6',
    marginBottom: '30px',
  },
  linkContainer: {
    display: 'flex',
    alignItems: 'center',
    gap: '8px',
  },
  linkStyle: {
    textDecoration: 'none',
    color: '#000000',
    fontWeight: 500,
  },
  linkSeparator: {
    color: '#000000',
    opacity: 0.6,
  },
};

export default MinimalPortfolio;
